function saveSettings(e){e.preventDefault();const f=new FormData(e.target),s=structuredClone(data().settings);try{for(const [k]of settingFields){s[k]=Number(f.get(k));if(!Number.isFinite(s[k])||s[k]<0)throw Error('Tham s? ph?i l� s? kh�ng �m.');}if(Math.abs(s.wcof+s.wnon-1)>1e-8)throw Error('T?ng tr?ng s? COF v� NON ph?i b?ng 1.');for(const k of ['ntu','done','dependents'])if(!Number.isInteger(s[k]))throw Error('S? h? so v� ngu?i ph? thu?c ph?i l� s? nguy�n.');for(const k of ['ntu','cash','bonus'])s.bands[k]=parseBands(f.get('band-'+k));s.taxBands=parseBands(f.get('taxBands'));data().settings=s;save();toast('Da luu tham s? th�ng.');render();}catch(err){toast(err.message);}}
