function validBackup(x){if(!x||typeof x.month!=='string'||!x.months||!x.months[x.month])return false;for(const [m,d]of Object.entries(x.months)){if(!/^\d{4}-\d{2}$/.test(m)||!d?.settings||!Array.isArray(d.cash)||!Array.isArray(d.ntu))return false;for(const[k]of settingFields)if(!Number.isFinite(d.settings[k])||d.settings[k]<0)return false;if(Math.abs(d.settings.wcof+d.settings.wnon-1)>1e-8)return false;for(const k of ['ntu','cash','bonus'])parseBands(d.settings.bands[k].map(r=>r.join(',')).join('\n'));parseBands(d.settings.taxBands.map(r=>r.join(',')).join('\n'));for(const r of [...d.cash,...d.ntu])if(typeof r.id!=='string'||typeof r.name!=='string'||typeof r.contract!=='string'||!Number.isFinite(r.amount)||r.amount<0||!Number.isFinite(r.manual)||r.manual<0)return false;for(const r of d.cash)if(!['COF','NON'].includes(r.group)||!kinds.some(k=>k[0]===r.kind))return false;for(const r of d.ntu)if(!Number.isFinite(r.pos)||r.pos<=0||!Number.isFinite(r.mindue)||r.mindue<=0||r.manual>1||(r.override!==null&&(!Number.isFinite(r.override)||r.override<0||r.override>1)))return false;if(!Number.isFinite(calculate(d).net))return false;}return true;}
async function importFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('B?n sao luu qu� l?n.');const x=JSON.parse(await file.text());if(!validBackup(x))throw Error('B?n sao luu kh�ng h?p l?.');if(!confirm('Nh?p b?n sao luu s? thay to�n b? d? li?u tr�n tr�nh duy?t n�y. Ti?p t?c?'))return;state=x;scenario=null;$('#month').value=state.month;save();render();toast('Da kh�i ph?c b?n sao luu.');}catch(err){toast(err.message||'Kh�ng d?c du?c b?n sao luu.');}}
document.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;render();window.scrollTo(0,0);});$('#month').addEventListener('change',e=>{if(!e.target.value)return;const m=e.target.value;if(!state.months[m]){if(!confirm('T?o th�ng m?i v?i danh s�ch tr?ng? Tham s? du?c sao ch�p t? th�ng hi?n t?i.')){e.target.value=state.month;return;}const d=blank();d.settings=structuredClone(data().settings);d.settings.done=0;d.settings.company=null;state.months[m]=d;}state.month=m;scenario=null;save();render();});$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.list){list=b.dataset.list;render();return;}if(b.dataset.edit){editor(b.dataset.edit);return;}switch(b.dataset.action){case'add':editor();break;case'company':{const v=$('[name=company]').value;if(v!==''&&(!Number.isFinite(Number(v))||Number(v)<0)){toast('S? d?i chi?u ph?i kh�ng �m.');break;}data().settings.company=v===''?null:Number(v);save();render();break;}case'reset-sim':if(confirm('B? c�c gi? d?nh v� l?y l?i d? li?u th?c t??')){scenario=structuredClone(data());render();}break;case'sim-done':{const v=Number($('#sim-done').value);if(v>=0&&Number.isInteger(v)){scenario.settings.done=v;render();}else toast('S? h? so ph?i l� s? nguy�n kh�ng �m.');break;}case'export':exportData();break;case'import':$('#import-file').click();break;}});save();render();

